 if ( ! defined( 'ABSPATH' ) ) { exit; } add_action( 'init', function () { $cpts = array( 'mixer' => array( 'Mixer', 'Mixers', 'mixers', 'dashicons-groups' ), 'conference' => array( 'Conference', 'Conferences', 'conferences', 'dashicons-microphone' ), 'summit' => array( 'Summit', 'Summits', 'summits', 'dashicons-awards' ), 'speaker' => array( 'Speaker', 'Speakers', 'speakers', 'dashicons-businessperson' ), ); $pos = 5; foreach ( $cpts as $slug => $c ) { list( $single, $plural, $rewrite, $icon ) = $c; register_post_type( $slug, array( 'labels' => array( 'name' => $plural, 'singular_name' => $single, 'menu_name' => $plural, 'add_new_item' => 'Add New ' . $single, 'edit_item' => 'Edit ' . $single, 'all_items' => 'All ' . $plural, 'search_items' => 'Search ' . $plural, 'not_found' => 'No ' . strtolower( $plural ) . ' found', ), 'public' => true, 'has_archive' => true, 'menu_icon' => $icon, 'menu_position' => $pos++, 'rewrite' => array( 'slug' => $rewrite, 'with_front' => false ), 'supports' => array( 'title', 'thumbnail', 'editor' ), 'show_in_rest' => true, ) ); } } ); add_action( 'after_switch_theme', function () { if ( function_exists( 'flush_rewrite_rules' ) ) { flush_rewrite_rules(); } } ); 